		/** 
		 * Tests creating a new Wallet.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a Wallet");

			StringBuilder msg = new StringBuilder( "-- Failed to create a Wallet" );

			try {            
				Wallet entity = WalletService.getWalletInstance().createWallet( generateNewEntity() );
				thePrimaryKey = entity.getWalletId();
				LOGGER.info( "-- Successfully created a Wallet with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a Wallet. 
		 */
		public Wallet testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created Wallet" );

			Wallet entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read Wallet with primary key" );
			msg.append( thePrimaryKey );
			
			WalletFetchOneSummary fetchOneSummary = new WalletFetchOneSummary( thePrimaryKey );

			try {
				entity = WalletService.getWalletInstance().getWallet( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found Wallet " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a Wallet.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a Wallet." );

			StringBuilder msg = new StringBuilder( "Failed to update a Wallet : " );        
			Wallet entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created Wallet." );

				// for use later on...
				thePrimaryKey = entity.getWalletId();

				WalletService proxy = WalletService.getWalletInstance();            
				proxy.updateWallet( entity );   

				LOGGER.info( "-- Successfully saved Wallet - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a Wallet.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created Wallet." );

			try{
			    Wallet entity = testRead(); 
				WalletService.getWalletInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted Wallet with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete Wallet with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all Wallets.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of Wallets:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all Wallet : " );        
			List<Wallet> collection  = null;

			try {
				// call the static get method on the WalletService
				collection = WalletService.getWalletInstance().getAllWallet();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					Wallet entity = null;            
					Iterator<Wallet> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getWalletId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

